// --- widget.h --- (Client-facing header)
#include <memory>

class Widget {
public:
    Widget();
    ~Widget(); // Destructor MUST be declared here...

    // Support for move and copy operations
    Widget(Widget&&) noexcept; 
    Widget& operator=(Widget&&) noexcept;
    Widget(const Widget&); 
    Widget& operator=(const Widget&);

private:
    struct Impl; // Forward-declare the implementation struct
    std::unique_ptr<Impl> pImpl; // Use unique_ptr for Pimpl
};

// --- widget.cpp --- (Implementation file)
#include "widget.h"
#include <string>
#include <vector>

// Full definition of the implementation struct
struct Widget::Impl {
    std::string name;
    std::vector<int> data;
};

// ...and defined here, where Impl is a complete type.
Widget::Widget() : pImpl(std::make_unique<Impl>()) {}
Widget::~Widget() = default; // Now compiler can generate destructor

// Move operations can also be defaulted here
Widget::Widget(Widget&&) noexcept = default;
Widget& Widget::operator=(Widget&&) noexcept = default;

// Copy operations require a deep copy
Widget::Widget(const Widget& rhs)
    : pImpl(std::make_unique<Impl>(*rhs.pImpl)) // Copy the Impl object
{}

Widget& Widget::operator=(const Widget& rhs)
{
    if (this != &rhs) {
        *pImpl = *rhs.pImpl; // Copy-assign the Impl object
    }
    return *this;
}
